export type DialogOpenChangeReason =
  | 'close-button'
  | 'escape-key'
  | 'outside-press'
  | 'trigger'

export type DialogOpenChangeDetails = {
  reason: DialogOpenChangeReason
}

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentId: string
  descriptionId: string
  open: boolean
  requestOpenChange: (open: boolean, reason: DialogOpenChangeReason) => void
  titleId: string
}

const DialogContext = createContext<DialogContextValue | null>(null)

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)

  if (!context) {
    throw new Error(`${componentName} must be rendered inside Dialog.Root.`)
  }

  return context
}

function setRefs<T>(value: T, ...refs: Array<Ref<T> | undefined>) {
  for (const ref of refs) {
    if (typeof ref === 'function') {
      ref(value)
    } else if (ref) {
      ref.current = value
    }
  }
}

const useBrowserLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

/** Owns only the open state and stable accessible relationships. */
export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const open = isControlled ? controlledOpen : uncontrolledOpen
  const isControlledRef = useRef(isControlled)
  const onOpenChangeRef = useRef(onOpenChange)
  const reactId = useId()
  const idPrefix = `dialog-${reactId}`
  isControlledRef.current = isControlled
  onOpenChangeRef.current = onOpenChange

  const requestOpenChange = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason) => {
      if (!isControlledRef.current) {
        setUncontrolledOpen(nextOpen)
      }
      onOpenChangeRef.current?.(nextOpen, { reason })
    },
    [],
  )

  const value = useMemo<DialogContextValue>(
    () => ({
      contentId: `${idPrefix}-content`,
      descriptionId: `${idPrefix}-description`,
      open,
      requestOpenChange,
      titleId: `${idPrefix}-title`,
    }),
    [idPrefix, open, requestOpenChange],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export type DialogTriggerProps = ComponentPropsWithoutRef<'button'>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger({ onClick, type = 'button', ...props }, forwardedRef) {
    const { contentId, open, requestOpenChange } = useDialogContext('Dialog.Trigger')

    const handleClick = (event: ReactMouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (!event.defaultPrevented) {
        event.currentTarget.focus()
        requestOpenChange(true, 'trigger')
      }
    }

    return (
      <button
        {...props}
        aria-controls={open ? contentId : undefined}
        aria-expanded={open}
        aria-haspopup="dialog"
        data-state={open ? 'open' : 'closed'}
        onClick={handleClick}
        ref={forwardedRef}
        type={type}
      />
    )
  },
)

export type DialogPortalProps = {
  children: ReactNode
  container?: Element | DocumentFragment
}

/** Defers the portal until after mount so server output and hydration agree. */
export function DialogPortal({ children, container }: DialogPortalProps) {
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) {
    return null
  }

  return createPortal(children, container ?? document.body)
}

const focusableSelector = [
  '[autofocus]',
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

function focusInitialElement(dialog: HTMLDialogElement, initialFocus?: RefObject<HTMLElement | null>) {
  const requestedElement = initialFocus?.current
  if (requestedElement?.isConnected && dialog.contains(requestedElement)) {
    requestedElement.focus()
    return
  }

  if (dialog.contains(dialog.ownerDocument.activeElement)) {
    return
  }

  dialog.querySelector<HTMLElement>(focusableSelector)?.focus()
}

export type DialogContentProps = Omit<
  ComponentPropsWithoutRef<'dialog'>,
  'aria-modal' | 'id' | 'open' | 'role'
> & {
  /** Focused after opening; falls back to the browser's first-focusable behavior. */
  initialFocus?: RefObject<HTMLElement | null>
  /** Set false only when the product deliberately owns focus after dismissal. */
  restoreFocus?: boolean
}

export const DialogContent = forwardRef<HTMLDialogElement, DialogContentProps>(
  function DialogContent(
    {
      'aria-label': ariaLabel,
      children,
      initialFocus,
      onCancel,
      onClick,
      restoreFocus = true,
      ...props
    },
    forwardedRef,
  ) {
    const {
      contentId,
      descriptionId,
      open,
      requestOpenChange,
      titleId,
    } = useDialogContext('Dialog.Content')
    const dialogRef = useRef<HTMLDialogElement>(null)
    const activationRef = useRef(0)
    const initialFocusRef = useRef(initialFocus)
    const restoreFocusRef = useRef(restoreFocus)

    initialFocusRef.current = initialFocus
    restoreFocusRef.current = restoreFocus

    useBrowserLayoutEffect(() => {
      if (!open) {
        return
      }

      const dialog = dialogRef.current
      if (!dialog) {
        return
      }

      const activation = ++activationRef.current
      const previouslyFocused = dialog.ownerDocument.activeElement
      const HTMLElementConstructor = dialog.ownerDocument.defaultView?.HTMLElement

      if (!dialog.open) {
        dialog.showModal()
      }
      focusInitialElement(dialog, initialFocusRef.current)

      return () => {
        if (dialog.open) {
          dialog.close()
        }

        queueMicrotask(() => {
          if (
            activationRef.current === activation &&
            restoreFocusRef.current &&
            HTMLElementConstructor &&
            previouslyFocused instanceof HTMLElementConstructor &&
            previouslyFocused.isConnected
          ) {
            previouslyFocused.focus()
          }
        })
      }
    }, [open])

    if (!open) {
      return null
    }

    return (
      <dialog
        {...props}
        aria-describedby={props['aria-describedby'] ?? descriptionId}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabel ? undefined : (props['aria-labelledby'] ?? titleId)}
        aria-modal="true"
        data-state="open"
        id={contentId}
        onCancel={(event) => {
          onCancel?.(event)
          const dismissalPrevented = event.defaultPrevented
          // State remains the single owner of visibility; prevent the browser from
          // mutating the native open state behind a controlled consumer's back.
          event.preventDefault()
          if (!dismissalPrevented) {
            requestOpenChange(false, 'escape-key')
          }
        }}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented && event.target === event.currentTarget) {
            requestOpenChange(false, 'outside-press')
          }
        }}
        ref={(node) => setRefs(node, dialogRef, forwardedRef)}
        role="dialog"
      >
        {children}
      </dialog>
    )
  },
)

