import { expect, test } from '@playwright/test'
import { readFile } from 'node:fs/promises'
import { extname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const demoRoot = fileURLToPath(new URL('../dist/demo/', import.meta.url))
const contentTypes: Record<string, string> = {
  '.css': 'text/css',
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.map': 'application/json',
}

test.beforeEach(async ({ page }) => {
  await page.route('http://dialog.test/**', async (route) => {
    const url = new URL(route.request().url())
    const requestedPath = decodeURIComponent(url.pathname).replace(/^\/+/, '') || 'index.html'
    const filePath = join(demoRoot, requestedPath)

    if (!filePath.startsWith(demoRoot)) {
      await route.fulfill({ status: 400 })
      return
    }

    try {
      await route.fulfill({
        body: await readFile(filePath),
        contentType: contentTypes[extname(filePath)] ?? 'application/octet-stream',
      })
    } catch {
      await route.fulfill({
        body: await readFile(join(demoRoot, 'index.html')),
        contentType: 'text/html',
      })
    }
  })
})

test('traps focus, closes with Escape, and restores the trigger', async ({ page }) => {
  await page.goto('/')
  const trigger = page.getByRole('button', { name: 'Edit profile' })
  await trigger.click()

  const dialog = page.getByRole('dialog', { name: 'Edit profile' })
  await expect(dialog).toBeVisible()
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Shift+Tab')
  await expect(dialog.getByRole('button', { name: 'Close' })).toBeFocused()
  await page.keyboard.press('Tab')
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(dialog).toBeHidden()
  await expect(trigger).toBeFocused()
})

test('only the top nested dialog handles Escape and restores local focus', async ({ page }) => {
