test('exposes stable accessible relationships from the portaled content', async ({ page }) => {
  await page.goto('/')
  await page.getByRole('button', { name: 'Edit profile' }).click()

  const dialog = page.getByRole('dialog', { name: 'Edit profile' })
  const title = dialog.getByRole('heading', { name: 'Edit profile' })
  const description = dialog.getByText('Update your public information.')
  const titleId = await title.getAttribute('id')
  const descriptionId = await description.getAttribute('id')

  expect(titleId).not.toBeNull()
  expect(descriptionId).not.toBeNull()
  await expect(dialog).toHaveAttribute('aria-labelledby', titleId!)
  await expect(dialog).toHaveAttribute('aria-describedby', descriptionId!)
  await expect(dialog).toHaveAttribute('aria-modal', 'true')
